// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor) public {
        // Owner is uninitialized (address(0)); any non-owner caller must be rejected.
        vm.assume(actor != address(0));

        vm.prank(actor);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }

        // General rule: `owned` never succeeds for a non-owner caller.
        assertTrue(!ok);
    }
}
